const {vec} = NMath;
const samples = await IO.loadMNIST();
const K = 10;
const eigenK = 16;
const pcaDimensions = 32;
const knnNeighbors = 10;
if (samples.length < K) throw new Error("At least 10 MNIST images are required");

const pca = PCA.new(samples, Math.min(pcaDimensions, samples.length - 1));
// Use unwhitened PCA coordinates so Euclidean distances retain variance scale.
const points = samples.map(sample => {
    const centered = vec.fromArray(Array.from(sample)).sub(pca.mean);
    return vec.fromArray(pca.components.map(component => component.dot(centered)));
});
if (points.some(point => point.toArray().some(value => !Number.isFinite(value)))) {
    throw new Error("PCA produced non-finite coordinates");
}

const graph = Graph.knn(points, Math.min(knnNeighbors, samples.length - 1), (a, b) => a.sub(b).length());
const edges = graph.getEdges();
const sigma = edges.reduce((sum, edge) => sum + edge.weight, 0) / edges.length;
if (!Number.isFinite(sigma) || sigma <= 0) throw new Error("PCA points have no non-zero neighbor distances");
const laplacian = graph.laplacian((a, b) => {
    const distance = graph.getEdge(a.id, b.id).weight;
    return Math.exp(-(distance ** 2) / (2 * sigma ** 2));
});
const {eigenvectors} = laplacian.eigen({maxFirst: false, k: Math.min(eigenK, samples.length)});
const eigenArrays = eigenvectors.map(vector => vector.toArray());
const spectralPoints = samples.map((_, i) => eigenArrays.map(vector => vector[i]));
if (spectralPoints.some(point => point.some(value => !Number.isFinite(value)))) {
    throw new Error("Graph Laplacian produced non-finite coordinates");
}

const kmeans = Kmeans.new(spectralPoints, K, {maxIterations: 30}).fit();
const means = Array.from({length: K}, () => new Float32Array(28 * 28));
const counts = new Array(K).fill(0);
for (let n = 0; n < samples.length; n++) {
    const cluster = kmeans.predictIndex(spectralPoints[n]);
    counts[cluster]++;
    for (let i = 0; i < samples[n].length; i++) means[cluster][i] += samples[n][i];
}
for (let cluster = 0; cluster < K; cluster++) {
    if (counts[cluster] === 0) {
        console.warn(`Cluster ${cluster} is empty`);
        continue;
    }
    for (let i = 0; i < means[cluster].length; i++) means[cluster][i] /= counts[cluster];
}
IO.paintMNIST(means, 5);
